\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{tikz}
\usetikzlibrary{arrows.meta,positioning,shapes.geometric,calc}
\pagestyle{empty}

% ── IEEE S&P Dark Security Theme ──
\definecolor{bgdark}{HTML}{0F172A}
\definecolor{cardbg}{HTML}{1E293B}
\definecolor{cardalt}{HTML}{162032}
\definecolor{accent}{HTML}{06B6D4}
\definecolor{accentblue}{HTML}{3B82F6}
\definecolor{textwhite}{HTML}{F1F5F9}
\definecolor{textsecondary}{HTML}{94A3B8}
\definecolor{success}{HTML}{10B981}
\definecolor{warning}{HTML}{F59E0B}
\definecolor{danger}{HTML}{EF4444}
\definecolor{statbg}{HTML}{0D1B2A}
\definecolor{titlebg}{HTML}{0A1628}
\definecolor{tealfaint}{HTML}{083344}
\definecolor{bluefaint}{HTML}{172554}
\definecolor{navycard}{HTML}{1A2744}

\pagecolor{bgdark}
\color{textwhite}

% ── List styling ──
\setlist[itemize]{leftmargin=20pt, itemsep=5pt, parsep=1pt, topsep=2pt,
  label={\color{accent}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=20pt, itemsep=5pt, parsep=1pt, topsep=2pt,
  label={\color{accent}\bfseries\arabic*.}}

% ── Dark card styles ──
\tcbset{
  darkcard/.style={
    enhanced, arc=3pt, boxrule=0pt, colback=cardbg,
    borderline west={4pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=cardalt,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=1.5pt, titlerule style={accent!40},
    valign=top, drop shadow={opacity=0.3,color=black},
  },
  bluecard/.style={
    enhanced, arc=3pt, boxrule=0pt, colback=cardbg,
    borderline west={4pt}{0pt}{accentblue},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{accentblue},
    coltitle=accentblue, colbacktitle=bluefaint,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=1.5pt, titlerule style={accentblue!40},
    valign=top, drop shadow={opacity=0.3,color=black},
  },
  tealcard/.style={
    enhanced, arc=3pt, boxrule=0pt, colback=navycard,
    borderline west={4pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=tealfaint,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=1.5pt, titlerule style={accent!40},
    valign=top, drop shadow={opacity=0.3,color=black},
  },
  highlightcard/.style={
    enhanced, arc=3pt, boxrule=0pt, colback=tealfaint,
    borderline west={5pt}{0pt}{success},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{success},
    coltitle=white, colbacktitle=success!30!bgdark,
    toptitle=6pt, bottomtitle=6pt,
    valign=top, drop shadow={opacity=0.3,color=black},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=2mm},
]

% ══════════════════════════════════════════════════════════════
% TITLE BAR
% ══════════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=titlebg, colframe=titlebg, colupper=textwhite,
  arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=10pt, bottom=6pt,
  halign=center, valign=center,
  borderline south={3pt}{0pt}{accent},
]{name=title, column=1, span=2, between=top and row3}{
  {\fontsize{42}{50}\selectfont\bfseries\color{textwhite}
  Bot Mitigation at Scale: How Modern Web Security}\\[4pt]
  {\fontsize{42}{50}\selectfont\bfseries\color{textwhite}
  Services Protect Scientific Publishing Platforms}\\[10pt]
  {\fontsize{22}{28}\selectfont\color{textsecondary}
  An analysis of challenge-based bot verification systems safeguarding high-value academic web properties}\\[8pt]
  {\fontsize{18}{24}\selectfont\color{accent}
  IEEE Symposium on Security and Privacy (S\&P) \quad$\boldsymbol{\vert}$\quad CDN Security \quad$\boldsymbol{\vert}$\quad Bot Mitigation \quad$\boldsymbol{\vert}$\quad Academic Publishing}
}

% ══════════════════════════════════════════════════════════════
% STATS BANNER — 5 key metrics (85% and 99.97% are heroes)
% ══════════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=statbg, boxrule=0pt, arc=0pt,
  left=8pt, right=8pt, top=4pt, bottom=4pt,
  valign=center,
  borderline south={2pt}{0pt}{accent!30},
]{name=stats, column=1, span=2, between=row3 and row6}{
  \centering
  \begin{minipage}[c]{0.175\linewidth}\centering
    \fcolorbox{warning!60}{warning!12!bgdark}{\parbox{0.88\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{42}{50}\selectfont\bfseries\color{warning} \raisebox{-2pt}{\texttildelow}47\%}\\[2pt]
      {\fontsize{16}{20}\selectfont\color{textsecondary} Internet Traffic\\ from Bots}\vspace{4pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.175\linewidth}\centering
    \fcolorbox{danger!60}{danger!12!bgdark}{\parbox{0.88\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{42}{50}\selectfont\bfseries\color{danger} 30\%}\\[2pt]
      {\fontsize{16}{20}\selectfont\color{textsecondary} Classified as\\ Malicious}\vspace{4pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.22\linewidth}\centering
    \fcolorbox{accent}{accent!18!bgdark}{\parbox{0.88\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{54}{64}\selectfont\bfseries\color{accent} 85\%}\\[2pt]
      {\fontsize{17}{22}\selectfont\color{textwhite} Reduction in\\ Scraping Attempts}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.22\linewidth}\centering
    \fcolorbox{success}{success!18!bgdark}{\parbox{0.88\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{50}{60}\selectfont\bfseries\color{success} 99.97\%}\\[2pt]
      {\fontsize{17}{22}\selectfont\color{textwhite} Uptime During\\ Bot Surges}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.175\linewidth}\centering
    \fcolorbox{accentblue!60}{accentblue!12!bgdark}{\parbox{0.88\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{42}{50}\selectfont\bfseries\color{accentblue} {<}2s}\\[2pt]
      {\fontsize{16}{20}\selectfont\color{textsecondary} Verification\\ Latency}\vspace{4pt}%
    }}
  \end{minipage}
}

% ══════════════════════════════════════════════════════════════
% THREAT LANDSCAPE (left column, row6-row10)
% ══════════════════════════════════════════════════════════════
\posterbox[darkcard, title={The Bot Threat Landscape}
]{name=threat, column=1, between=row6 and row10}{
  \fontsize{20}{26}\selectfont\color{textwhite}
  \begin{itemize}[itemsep=8pt]
    \item {\bfseries\color{warning}\raisebox{-1pt}{\texttildelow}47\% of internet traffic} from bots (2024)
    \item {\bfseries\color{danger}\raisebox{-1pt}{\texttildelow}30\% classified as malicious} --- credential stuffing, scraping, DDoS
    \item Academic publishers face {\bfseries disproportionate scraping} --- high-value peer-reviewed content + DOIs
    \item Platforms like {\ttfamily www.science.org} serve millions of researchers, educators, and policymakers
  \end{itemize}
  \vspace{6pt}
  \colorbox{warning!15!bgdark}{\parbox{0.92\linewidth}{%
    \centering\vspace{4pt}%
    {\fontsize{18}{24}\selectfont\color{warning}\bfseries Key Insight:}
    {\fontsize{18}{24}\selectfont\color{textwhite} \raisebox{-1pt}{\texttildelow}1.2M scraping attempts/day before mitigation}%
    \vspace{4pt}%
  }}
}

% ══════════════════════════════════════════════════════════════
% PIPELINE OVERVIEW TEXT (right column, row6-row10)
% ══════════════════════════════════════════════════════════════
\posterbox[bluecard, title={CDN-Edge Security Architecture}
]{name=pipetext, column=2, between=row6 and row10}{
  \fontsize{20}{26}\selectfont\color{textwhite}
  \begin{itemize}[itemsep=8pt]
    \item CDN-level interception at {\bfseries edge nodes} before origin server
    \item Multi-signal threat scoring: {\bfseries IP reputation}, TLS fingerprint, behavioral analysis
    \item JavaScript / CAPTCHA challenges for suspicious requests
    \item Traceable {\bfseries Ray IDs} enable continuous monitoring and optimization
    \item Total pipeline latency for humans: {\bfseries\color{accent} {<}2 seconds}
  \end{itemize}
  \vspace{6pt}
  \colorbox{accentblue!15!bgdark}{\parbox{0.92\linewidth}{%
    \centering\vspace{4pt}%
    {\fontsize{18}{24}\selectfont\color{accentblue}\bfseries Result:}
    {\fontsize{18}{24}\selectfont\color{textwhite} Automated scripts blocked entirely; humans pass seamlessly}%
    \vspace{4pt}%
  }}
}

% ══════════════════════════════════════════════════════════════
% PIPELINE FLOW DIAGRAM (full width, row10-row14)
% ══════════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=cardalt, arc=3pt, boxrule=0pt,
  borderline north={2pt}{0pt}{accent!40},
  borderline south={2pt}{0pt}{accent!40},
  left=12pt, right=12pt, top=6pt, bottom=6pt,
  fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{accent},
  coltitle=accent, colbacktitle=tealfaint,
  toptitle=6pt, bottomtitle=6pt,
  title={Challenge-Based Verification Pipeline},
  drop shadow={opacity=0.3,color=black},
]{name=pipeline, column=1, span=2, between=row10 and row14}{
\centering
\begin{tikzpicture}[
  node distance=1mm and 6mm,
  stage/.style={
    rectangle, rounded corners=3pt,
    minimum width=88mm, minimum height=28mm,
    fill=tealfaint, draw=accent, line width=1.2pt,
    text width=82mm, align=center,
    font=\fontsize{17}{22}\selectfont\color{textwhite}
  },
  stagelabel/.style={
    font=\fontsize{14}{18}\selectfont\bfseries\color{accent},
  },
  timing/.style={
    font=\fontsize{16}{20}\selectfont\bfseries\color{success},
  },
  arr/.style={
    -{Stealth[length=5mm,width=4mm]},
    line width=1.8pt, color=accent!70,
  },
]
  \node[stage] (s1) {{\bfseries\color{accent}\fontsize{18}{22}\selectfont 1. Request Interception}\\[2pt]
    Incoming HTTP routed\\through CDN edge node};
  \node[timing, right=4mm of s1] {$<$50\,ms};

  \node[stage, right=14mm of s1.east, xshift=8mm] (s2) {{\bfseries\color{accent}\fontsize{18}{22}\selectfont 2. Threat Scoring}\\[2pt]
    IP reputation, TLS fingerprint,\\behavioral signals evaluated};
  \node[timing, right=4mm of s2] {\raisebox{-1pt}{\texttildelow}100\,ms};

  \node[stage, right=14mm of s2.east, xshift=8mm] (s3) {{\bfseries\color{accent}\fontsize{18}{22}\selectfont 3. Challenge Issuance}\\[2pt]
    JS or CAPTCHA challenge\\served if risk score exceeds threshold};
  \node[timing, right=4mm of s3] {\raisebox{-1pt}{\texttildelow}500\,ms};

  \node[stage, below=14mm of s1.south, xshift=0mm] (s4) {{\bfseries\color{accent}\fontsize{18}{22}\selectfont 4. Verification Check}\\[2pt]
    Client response validated;\\unique Ray ID assigned for tracing};
  \node[timing, right=4mm of s4] {\raisebox{-1pt}{\texttildelow}200\,ms};

  \node[stage, right=14mm of s4.east, xshift=8mm] (s5) {{\bfseries\color{success}\fontsize{18}{22}\selectfont 5. Access Grant}\\[2pt]
    Verified user forwarded to\\origin server with session token};
  \node[timing, right=4mm of s5] {$<$50\,ms};

  % Arrows
  \draw[arr] (s1.east) ++(4mm,0) -- (s2.west);
  \draw[arr] (s2.east) ++(4mm,0) -- (s3.west);
  \draw[arr] (s3.south) -- ++(0,-7mm) -| (s4.north);
  \draw[arr] (s4.east) ++(4mm,0) -- (s5.west);

  % Total latency callout
  \node[right=14mm of s5.east, xshift=8mm,
    rectangle, rounded corners=3pt,
    minimum width=66mm, minimum height=28mm,
    fill=success!15!bgdark, draw=success, line width=1.5pt,
    text width=58mm, align=center] (total) {
    {\fontsize{14}{18}\selectfont\color{textsecondary} Total Latency}\\[2pt]
    {\fontsize{30}{36}\selectfont\bfseries\color{success} {<}2 seconds}\\[2pt]
    {\fontsize{14}{18}\selectfont\color{textsecondary} for legitimate users}
  };
\end{tikzpicture}
}

% ══════════════════════════════════════════════════════════════
% PERFORMANCE OUTCOMES TABLE (left col, row14-row18)
% ══════════════════════════════════════════════════════════════
\posterbox[tealcard, title={Performance \& Security Outcomes}
]{name=outcomes, column=1, between=row14 and row18}{
  \fontsize{18}{24}\selectfont\color{textwhite}
  \centering
  \renewcommand{\arraystretch}{1.5}
  \begin{tabular}{p{60mm}@{\hspace{4mm}}c@{\hspace{4mm}}c}
    \rowcolor{accent!20!bgdark}
    {\bfseries\color{accent} Metric} & {\bfseries\color{danger} Before} & {\bfseries\color{success} After} \\
    \rowcolor{cardbg}
    Scraping attempts/day & \raisebox{-1pt}{\texttildelow}1.2M & \raisebox{-1pt}{\texttildelow}180K \\
    \rowcolor{cardalt}
    Origin server CPU load & 78\% & 42\% \\
    \rowcolor{cardbg}
    User complaints/month & 1,200 & 340 \\
    \rowcolor{cardalt}
    Uptime (bot surges) & 98.5\% & 99.97\% \\
  \end{tabular}
  \vspace{6pt}

  \colorbox{success!15!bgdark}{\parbox{0.92\linewidth}{%
    \centering\vspace{3pt}%
    {\fontsize{16}{20}\selectfont\color{success}\bfseries Only 0.3\% of legitimate users reported access friction}%
    \vspace{3pt}%
  }}
  \vspace{3pt}
  \colorbox{accentblue!12!bgdark}{\parbox{0.92\linewidth}{%
    \centering\vspace{3pt}%
    {\fontsize{16}{20}\selectfont\color{accentblue}\bfseries Average added latency: {<}150\,ms per verified session}%
    \vspace{3pt}%
  }}
}

% ══════════════════════════════════════════════════════════════
% TRADE-OFFS (right col, row14-row18)
% ══════════════════════════════════════════════════════════════
\posterbox[bluecard, title={Usability vs.\ Security Trade-offs}
]{name=tradeoffs, column=2, between=row14 and row18}{
  \fontsize{20}{26}\selectfont\color{textwhite}
  \begin{itemize}[itemsep=8pt]
    \item {\bfseries\color{accentblue} Accessibility} --- WCAG 2.1 compliance required for challenge pages
    \item {\bfseries\color{accentblue} Institutional Access} --- University IP allowlisting reduces unnecessary challenges
    \item {\bfseries\color{accentblue} Transparency} --- Clear messaging during verification reduces user anxiety
    \item {\bfseries\color{accentblue} Privacy} --- Threat detection must balance with user data disclosure practices
  \end{itemize}
  \vspace{6pt}
  \colorbox{accentblue!15!bgdark}{\parbox{0.92\linewidth}{%
    \centering\vspace{4pt}%
    {\fontsize{17}{22}\selectfont\color{textwhite}\itshape
    Security verification is essential, but the friction--protection\\balance requires continuous calibration}%
    \vspace{4pt}%
  }}
}

% ══════════════════════════════════════════════════════════════
% KEY TAKEAWAYS (full width, row18-bottom)
% ══════════════════════════════════════════════════════════════
\posterbox[highlightcard, title={Key Takeaways}
]{name=takeaways, column=1, span=2, between=row18 and bottom}{
  \fontsize{20}{26}\selectfont\color{textwhite}
  \begin{minipage}[t]{0.47\linewidth}
    \begin{enumerate}[itemsep=8pt]
      \item Bot traffic $\approx$ {\bfseries half of all requests} to academic publisher websites
      \item Multi-stage CDN-edge verification blocks {\bfseries vast majority of malicious bots} with minimal human impact
    \end{enumerate}
  \end{minipage}\hfill
  \begin{minipage}[t]{0.47\linewidth}
    \begin{enumerate}[itemsep=8pt, start=3]
      \item Traceable identifiers (Ray IDs) enable {\bfseries continuous optimization} of the security--usability balance
      \item Publisher--CDN collaboration is {\bfseries critical} for sustaining open, secure access to scientific knowledge
    \end{enumerate}
  \end{minipage}
}

\end{tcbposter}
\end{document}
LATEX_EOF
